// Catalogo esercizi. Nomi e istruzioni nell'ordine delle lingue: it, en, es, fr, de, pt.
// muscle = muscolo principale; secondary = muscoli secondari (contano metà nel recupero e nelle serie settimanali).
// timed = la "ripetizione" è in secondi. bw = esercizio a corpo libero (volume misurato in ripetizioni).

export const LANGS = ['it', 'en', 'es', 'fr', 'de', 'pt'];

export const MUSCLES = ['chest', 'back', 'shoulders', 'biceps', 'triceps', 'core', 'quads', 'hamstrings', 'glutes', 'calves'];

export const EQUIPMENT = ['barbell', 'dumbbell', 'machine', 'cable', 'bodyweight'];

// Muscoli grandi: recupero completo in ~72 h; piccoli in ~48 h.
export const RECOVERY_HOURS = {
  chest: 72, back: 72, quads: 72, hamstrings: 72, glutes: 72,
  shoulders: 48, biceps: 48, triceps: 48, core: 48, calves: 48
};

const L = arr => Object.fromEntries(LANGS.map((l, i) => [l, arr[i]]));

function ex(id, muscle, secondary, equipment, level, kind, def, name, steps, extra = {}) {
  return {
    id, muscle, secondary, equipment, level, kind,
    w: def[0], r: def[1], sets: def[2] || 3, rest: def[3] || (kind === 'compound' ? 120 : 75),
    name: L(name), steps: L(steps), timed: false, ...extra
  };
}

